mapper.select:
SELECT ur.id, ur.user_id, ur.role_id, r.id AS r_id, r.code AS r_code, r.name AS r_name, r.description AS r_description, r.created_at AS r_created_at FROM pjt_user_roles ur JOIN pjt_roles r ON r.id = ur.role_id WHERE ur.user_id IN
#{userId}
ORDER BY ur.user_id ASC, ur.id ASC

SELECT EXISTS(
    SELECT 1
    FROM pjt_user_roles ur
    JOIN pjt_users u ON u.id = ur.user_id
    JOIN pjt_roles r ON r.id = ur.role_id
    WHERE u.email = #{email}
      AND r.code = #{roleCode}
)
